/// <summary>
/// Modified method.
/// </summary>
public void modified()
{
    FormDataSource  vendInvoiceInfoLineDS = this.datasource();
    VendInvoiceInfoLine line = vendInvoiceInfoLineDS.cursor();
    FormRun formRun = vendInvoiceInfoLineDS.formRun();

    next modified();

    boolean isNoDelivery = false;

    if (line.ItemId)
    {
        ReasonTable reasonCode = line.metGetNoDeliveryReasonCode();
        if (reasonCode.RecId)
        {
            isNoDelivery = true;
        }
    }

    formRun.control(formRun.controlId(formControlStr(VendEditInvoice, METEditReasonCode))).allowEdit(!isNoDelivery);
    formRun.control(formRun.controlId(formControlStr(VendEditInvoice, METeditPriceReasonCode))).allowEdit(!isNoDelivery);
    vendInvoiceInfoLineDS.object(fieldNum(VendInvoiceInfoLine, MetClaimLine)).allowEdit(!isNoDelivery);
}
